S = "Hakeem Force Academy"
QS = [
(S, "Which of the following Sahabah was NOT among the Ashra Mubashira (the ten companions given the glad tidings of Paradise)?", ["Hazrat Talha bin Ubaidullah (RA)", "Hazrat Zubair bin Awwam (RA)", "Hazrat Abu Hurairah (RA)", "Hazrat Abdur Rahman bin Auf (RA)"], 2,
 "Talha, Zubair and Abdur Rahman bin Auf are all in the list of ten promised Paradise in one hadith. Abu Hurairah, a great narrator of hadith, is not in that list.",
 "The ten are Abu Bakr, Umar, Uthman, Ali, Talha, Zubair, Abdur Rahman bin Auf, Saad bin Abi Waqqas, Saeed bin Zaid and Abu Ubaidah bin Jarrah (RA).", 1),
(S, "Which surah of the Holy Quran is named after the ant?", ["Al-Naml", "Al-Nahl", "Al-Ankabut", "Al-Fil"], 0,
 "Surah Al-Naml (the Ant), the 27th surah, takes its name from the story of the ant that warned its colony about Hazrat Sulaiman (AS) and his army.",
 "Al-Nahl is the surah named after the bee and Al-Ankabut the one named after the spider.", 1),
(S, "Which two oceans does the Panama Canal connect?", ["Atlantic and Pacific Oceans", "Atlantic and Indian Oceans", "Pacific and Indian Oceans", "Arctic and Atlantic Oceans"], 0,
 "The Panama Canal cuts across the Isthmus of Panama and joins the Atlantic Ocean (via the Caribbean Sea) with the Pacific Ocean. This saves ships the long voyage around South America.",
 "The Panama Canal was opened in 1914.", 1),
(S, "Which two surahs of the Holy Quran are together called Muawwazatain?", ["Al-Falaq and Al-Nas", "Al-Ikhlas and Al-Falaq", "Al-Kafirun and Al-Nas", "Al-Masad and Al-Ikhlas"], 0,
 "Surah Al-Falaq (113) and Surah Al-Nas (114) both begin with a request to seek refuge (ta'awwuz) with Allah. That is why the pair is called Muawwazatain.",
 "These are the last two surahs of the Quran and are commonly recited for protection.", 1),
(S, "Which was the first Muslim country to become a nuclear power?", ["Iran", "Pakistan", "Saudi Arabia", "Turkey"], 1,
 "Pakistan carried out its nuclear tests at Chagai on 28 May 1998 and became the first Muslim country with nuclear weapons.",
 "Pakistan became the seventh nuclear-armed country in the world, after India's tests earlier in May 1998.", 1),
(S, "Which wife of the Holy Prophet (PBUH) was the daughter of Hazrat Abu Bakr (RA)?", ["Hazrat Hafsa (RA)", "Hazrat Aisha (RA)", "Hazrat Khadija (RA)", "Hazrat Zainab bint Jahsh (RA)"], 1,
 "Hazrat Aisha (RA) was the daughter of Hazrat Abu Bakr Siddiq (RA) and was married to the Prophet (PBUH). Hazrat Hafsa (RA) was the daughter of Hazrat Umar (RA).",
 "Hazrat Aisha (RA) is one of the most important narrators of hadith.", 1),
(S, "Which defensive technique was used by the Muslims in the Battle of Khandaq (Trench) in 5 AH?", ["Digging a trench around Madinah", "Building a wall of stones around Makkah", "Fighting from the hills of Uhud", "A night surprise attack on the enemy camp"], 0,
 "On the advice of Hazrat Salman Farsi (RA), the Muslims dug a long trench across the open side of Madinah. The Quraish and their allies could not cross it and had to retreat.",
 "The battle is also called the Battle of Ahzab (the Confederates).", 1),
]
